"""Render the checked design-spec.json without duplicating product facts.
Run from this directory or with an absolute script path. The vendored SpatialUI
runtime stays unchanged; the output has no fetch, CDN or runtime dependency.
"""
from pathlib import Path
import json
HERE=Path(__file__).resolve().parent
SKILL=Path('/Users/yupeng/.codex/plugins/cache/pico-xr/pico-spatial-agentic-tools/0.6.1/skills/pico-spatial-app-designer')
spec=json.loads((HERE/'design-spec.json').read_text())
bundle=(SKILL/'assets/spatialui-web/spatialui.bundle.js').read_text()
asset={a['id']:(HERE/a['src']).read_text() for a in spec['assets']}
renderer=r'''
(()=>{
const spec=JSON.parse(document.getElementById('pico-design-spec').textContent), assets=JSON.parse(document.getElementById('pico-assets').textContent);
const teaching=spec.dataCases.normal.techniqueGuide;let guideIndex=teaching.initialIndex,inputMode=teaching.initialInputMode;
const nodes=new Map(spec.nodes.map(n=>[n.id,n])), actions=new Map(spec.actions.map(a=>[a.id,a]));
let stateId=spec.initialStateId,dataCase='normal',timer,selectedSize='defaultSize',damageSample='head',settlementSample=null;
const path=(o,p)=>p.split('.').reduce((v,k)=>v?.[k],o),kebab=s=>s.replace(/([a-z])([A-Z])/g,'$1-$2').toLowerCase();
const color=k=>spec.theme.brandColors[k]||`var(--sui-${kebab(k)})`;
function layout(el,l={}){el.style.display=l.mode==='grid'?'grid':'flex';el.style.flexDirection=l.mode==='row'?'row':'column';el.style.gap=(l.gapDp||0)+'px';if(l.widthDp)el.style.width=l.widthDp+'px';if(l.heightDp)el.style.height=l.heightDp+'px';if(l.minHeightDp!=null)el.style.minHeight=l.minHeightDp+'px';if(l.grow!=null){el.style.flexGrow=l.grow;el.style.flexBasis='0';}el.style.justifyContent=l.justify||'';el.style.alignItems=({start:'flex-start',end:'flex-end',center:'center',stretch:'stretch'})[l.align]||'';if(l.paddingDp!=null)el.style.padding=typeof l.paddingDp==='number'?l.paddingDp+'px':Object.values(l.paddingDp).map(x=>x+'px').join(' ');if(l.overflow)el.style.overflow=l.overflow==='scroll'?'auto':l.overflow;}
function renderNode(id,data){let n=nodes.get(id);if(!n||n.visibleInStates&&!n.visibleInStates.includes(stateId)||n.bindings?.visible&&!path(data,n.bindings.visible))return null;let el;
if(n.kind==='spatialui'){el=document.createElement(n.component);let p={...n.props};for(let[k,v]of Object.entries(n.bindings||{}))p[k]=path(data,v);for(let[k,v]of Object.entries(p)){if(k==='stateLayout'||k==='stateAppearance')continue;if(k.endsWith('Token')){el.setAttribute(kebab(k.replace('Token','')),color(v));continue}if(typeof v==='boolean')el.toggleAttribute(kebab(k),v);else el.setAttribute(kebab(k),v)}}
else if(n.kind==='media'){el=document.createElement('div');el.innerHTML=assets[n.assetId];el.querySelector('svg')?.setAttribute('width','100%');el.querySelector('svg')?.setAttribute('height','100%')}
else{el=document.createElement('div');if(n.kind==='text'){el.textContent=n.bindings?.content?path(data,n.bindings.content):n.content;const t=spec.theme.typography[n.textStyle.typography];Object.assign(el.style,{fontFamily:t.family,fontSize:t.sizeDp+'px',lineHeight:t.lineHeightDp+'px',fontWeight:t.weight,color:color(n.bindings?.color?path(data,n.bindings.color):(n.props?.stateColor?.[stateId]||n.textStyle.color)),textAlign:n.textStyle.align||'start',whiteSpace:'pre-line'});if(n.textStyle.maxLines===1)Object.assign(el.style,{whiteSpace:'nowrap',overflow:'hidden',textOverflow:'ellipsis'});}}
if(n.props?.shadow){const sh=n.props.shadow;el.style.textShadow=`${sh.offsetX}px ${sh.offsetY}px ${sh.blur}px ${color(sh.colorToken)}`;}el.id=n.id;el.dataset.nodeId=n.id;if(n.layout)layout(el,{...n.layout,...(n.props?.stateLayout?.[stateId]||{})});if(n.accessibilityLabel)el.setAttribute('aria-label',n.accessibilityLabel);const a={...(n.appearance||{}),...(n.props?.stateAppearance?.[stateId]||{})};if(a.fill){el.dataset.designSurface=n.id;el.style.setProperty('--pico-design-surface-fill',color(a.fill))}if(a.foreground)el.style.color=color(a.foreground);if(a.radiusDp!=null)el.style.borderRadius=a.radiusDp+'px';
for(let[e,action]of Object.entries(n.events||{}))el.addEventListener(e,()=>dispatch(action));for(let c of n.children||[]){let child=renderNode(c,data);if(child)el.append(child)}return el;}
function commit(t){if(!t)return;stateId=t.to;render();}
function confirm(t){clearTimeout(timer);let c=t.confirmation,d=document.createElement('sui-alert-dialog');d.setAttribute('title',c.title);d.setAttribute('message',c.body);for(let[label,fn]of [[c.cancelLabel,()=>{d.remove();render()}],[c.confirmLabel,()=>{d.remove();commit(t)}]]){let b=document.createElement('sui-button');b.slot='buttons';b.setAttribute('text',label);b.addEventListener('click-action',fn);d.append(b)}d.addEventListener('dismiss-request',()=>{d.remove();render()});document.body.append(d)}
function dispatch(id){let a=actions.get(id);if(!a)return;if(a.type==='increment'&&a.binding==='techniqueGuide.index'){guideIndex=Math.max(0,Math.min(teaching.steps.length-1,guideIndex+Number(a.value)));render();return;}if(a.type==='transition'){let t=spec.transitions.find(x=>x.id===a.transitionId&&x.from===stateId);if(t?.confirmation)confirm(t);else commit(t)}else if(a.payload?.triggerNodeIds){let t=spec.transitions.find(t=>t.from===stateId&&a.payload.triggerNodeIds.includes(t.trigger.nodeId));if(t){if(t.confirmation)confirm(t);else commit(t)}}else if(a.payload?.delayMs&&dataCase==='normal'){timer=setTimeout(()=>emit(a.payload.event),a.payload.delayMs)}}
function emit(event){commit(spec.transitions.find(t=>t.from===stateId&&t.trigger.event===event))}
function render(){clearTimeout(timer);let st=spec.states.find(s=>s.id===stateId),data={...spec.dataCases[dataCase].stateSamples[stateId],damage:spec.dataCases[dataCase].damageSamples?.[damageSample]};const terminalSample=spec.dataCases[dataCase].settlementSamples?.[settlementSample];if(terminalSample?.stateId===stateId)data={...data,...terminalSample.data};data.guide={current:teaching.steps[guideIndex],pageLabel:teaching.pageLabelFormat.replace('%1$d',guideIndex+1).replace('%2$d',teaching.steps.length),showKeys:teaching.inputModes[inputMode].showKeys,previousDisabled:guideIndex===0,nextDisabled:guideIndex===teaching.steps.length-1};document.documentElement.dataset.state=stateId;document.documentElement.dataset.dataCase=dataCase;document.documentElement.dataset.sampleResult=data.result||'';let mount=document.getElementById('mount');mount.replaceChildren();for(let s of spec.surfaces){let shell=document.createElement('section');shell.dataset.surfaceId=s.id;let dims=s[selectedSize];shell.style.width=dims.width+'px';shell.style.minHeight=dims.height+'px';let root=renderNode(st.surfaceRoots[s.id],data);if(root)shell.append(root);mount.append(shell)}requestAnimationFrame(()=>{document.querySelectorAll('sui-badge').forEach(el=>{const n=nodes.get(el.id),box=el.shadowRoot.querySelector('.badge').getBoundingClientRect();if(n.layout&&box.width){el.style.width=box.width+'px';el.style.height=box.height+'px';el.style.transformOrigin='left center';el.style.transform=`scale(${n.layout.widthDp/box.width},${n.layout.heightDp/box.height})`;}});document.querySelectorAll('sui-linear-progress').forEach(el=>{const ps=getComputedStyle(el.parentElement),w=el.parentElement.clientWidth-parseFloat(ps.paddingLeft)-parseFloat(ps.paddingRight);el.style.transformOrigin='left center';el.style.transform=`scaleX(${w/240})`;el.style.width=w+'px';})});if(st.entryAction)dispatch(st.entryAction)}
window.__arenaPreview={spec,get state(){return stateId},get dataCase(){return dataCase},get settlementSample(){return settlementSample},get techniquePage(){return guideIndex+1},get inputMode(){return inputMode},setInputMode(mode){if(teaching.inputModes[mode]){inputMode=mode;render()}},setSettlementSample(s){const sample=spec.dataCases[dataCase].settlementSamples?.[s];if(sample){settlementSample=s;stateId=sample.stateId;render()}},setState(s){if(spec.states.some(x=>x.id===s)){stateId=s;render()}},setDataCase(c){if(spec.dataCases[c]){dataCase=c;render()}},setDamageSample(s){if(spec.dataCases[dataCase].damageSamples?.[s]){damageSample=s;render()}},setSurfaceSize(s){if(['defaultSize','minSize'].includes(s)){selectedSize=s;render()}},emit};document.title=spec.metadata.projectName;document.documentElement.dataset.revision=spec.metadata.revision;render();
})();
'''
head='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title></title><style>
*{box-sizing:border-box}body{margin:0;padding:32px;background:#DAD6D3;background-image:none;font-family:system-ui,sans-serif}#mount{display:flex;align-items:flex-start;justify-content:center;gap:32px;flex-wrap:wrap}section{flex-shrink:0}section>div{overflow:hidden}[data-design-surface]{background:var(--pico-design-surface-fill)}sui-linear-progress{display:flex!important;max-width:100%}sui-linear-progress::part(track){max-width:100%}svg{display:block}div{min-width:0} @media(max-width:600px){body{padding:16px}#mount{gap:24px;align-items:center}section{max-width:100%}section>div{max-width:100%}}
</style></head><body><main id="mount"></main>'''
html=head+'<script>'+bundle+'</script>'+'<script id="pico-design-spec" type="application/json">'+json.dumps(spec,ensure_ascii=False)+'</script>'+'<script id="pico-assets" type="application/json">'+json.dumps(asset,ensure_ascii=False)+'</script><script>'+renderer+'</script></body></html>'
(HERE/'preview.html').write_text(html)
print('Rendered revision',spec['metadata']['revision'])
